// its three parameter copies to the reference-returning template: retail
// inlines both layers into center and selects one address before loading it.
template <class T>
static inline const T& t_limit(const T& minimum, const T& value,
                               const T& maximum)
{
    return value < minimum ? minimum
                           : (maximum < value ? maximum : value);
}

static inline int limit(int minimum, int value, int maximum)
{
    return t_limit(minimum, value, maximum);
}

